import java.io.*;
import java.util.*;

public class E {
    static final int MOD = 998_244_353;

    public static void main(String[] args) throws Exception {
        new E().run();
    }

    void run() throws Exception {
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        int n = fs.nextInt();
        int m = fs.nextInt();
        int l = fs.nextInt();
        int r = fs.nextInt();
        long power = 1L * n * m;
        long[][] base;

        if ((n & 1) == 1 && (m & 1) == 1) {
            long total = r - l + 1;
            base = new long[][]{{total, 0}, {0, total}};
        } else {
            int even = r / 2 - (l + 1) / 2 + 1;
            int odd = r - l + 1 - even;
            base = new long[][]{{even, odd}, {odd, even}};
        }

        long[][] res = matPow(base, power);
        out.println(res[0][0]);
        out.flush();
    }

    long[][] matPow(long[][] a, long e) {
        if (e == 0) {
            return new long[][]{{1, 0}, {0, 1}};
        }
        if (e == 1) {
            return a;
        }
        long[][] half = matPow(a, e >> 1);
        long[][] res = mul(half, half);
        if ((e & 1) == 1) {
            res = mul(res, a);
        }
        return res;
    }

    long[][] mul(long[][] a, long[][] b) {
        long[][] c = new long[2][2];
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 2; j++) {
                c[i][j] = (a[i][0] * b[0][j] + a[i][1] * b[1][j]) % MOD;
            }
        }
        return c;
    }

    static class FastScanner {
        BufferedReader reader;
        StringTokenizer tokenizer;

        FastScanner() {
            reader = new BufferedReader(new InputStreamReader(System.in), 32768);
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
